### Step 3: Add category filtering in `query_for_context()`

After collecting candidate lessons from phases 1 and 2 (before updating `last_surfaced`), batch-load categories and apply the filter.

```rust
// src/lessons.rs — const at module level
const KNOWN_LANGUAGE_CATEGORIES: &[&str] = &["rust", "dart"];

// Inside query_for_context(), after phase 2, before the last_surfaced update:
fn is_language_category(cat: &str) -> bool {
    KNOWN_LANGUAGE_CATEGORIES.iter().any(|&lc| lc.eq_ignore_ascii_case(cat))
}

// Batch-load categories for matched lessons
if !lessons.is_empty() && !ctx.workspace_languages.is_empty() {
    let ids: Vec<&str> = lessons.iter().map(|l| l.id.as_str()).collect();
    let placeholders = ids.iter().map(|_| "?").collect::<Vec<_>>().join(",");
    let mut stmt = conn.prepare(&format!(
        "SELECT lesson_id, tag FROM categories WHERE lesson_id IN ({placeholders})"
    ))?;
    let refs: Vec<&dyn rusqlite::types::ToSql> =
        ids.iter().map(|id| id as &dyn rusqlite::types::ToSql).collect();
    let mut cat_map: HashMap<String, Vec<String>> = HashMap::new();
    let mut rows = stmt.query(refs.as_slice())?;
    while let Some(row) = rows.next()? {
        let lid: String = row.get(0)?;
        let tag: String = row.get(1)?;
        cat_map.entry(lid).or_default().push(tag);
    }

    let ws_lang_set: HashSet<&str> = ctx.workspace_languages
        .iter().map(|s| s.as_str()).collect();

    lessons.retain(|l| {
        let cats = cat_map.get(&l.id);
        match cats {
            None => true, // uncategorized → universal
            Some(cats) if cats.is_empty() => true,
            Some(cats) => {
                cats.iter().any(|c| {
                    if is_language_category(c) {
                        ws_lang_set.contains(c.as_str())
                    } else {
                        true // non-language categories always relevant
                    }
                })
            }
        }
    });
}
```

When `workspace_languages` is empty, skip filtering entirely (no workspace context → surface everything).

